import subprocess, sys, json
EXE = '/workspace/executable'
def batch_widths(cps):
    fields = []
    for cp in cps:
        ch = chr(cp)
        fields.append('""""' if ch == '"' else '"' + ch + '"')
    hdr = ','.join(['""']*len(cps))
    data = ','.join(fields)
    inp = (hdr + '\n' + data + '\n').encode('utf-8')
    p = subprocess.run([EXE,'-P'], input=inp, capture_output=True)
    out = p.stdout.decode('utf-8')
    line = out.split('\n')[0]
    if not line.startswith('┌'):
        raise ValueError('bad start %r' % line[:40])
    segs = []
    cur = 0
    for ch in line[1:]:
        if ch == '─': cur += 1
        elif ch in '┬┐': segs.append(cur); cur = 0
        else: raise ValueError('bad border char %r' % ch)
    if len(segs) != len(cps): return None
    return [w-2 for w in segs]

results = {}
skip = {0x0A, 0x0D}
boxrange = set(range(0x2500, 0x25A0))
cps = [cp for cp in range(0x20, 0x110000) if not (0xD800 <= cp <= 0xDFFF) and cp not in skip and cp not in boxrange]
B = 400
i = 0; done = 0
while i < len(cps):
    chunk = cps[i:i+B]
    try:
        ws = batch_widths(chunk)
    except ValueError:
        ws = None
    if ws is None:
        for cp in chunk:
            results[cp] = batch_widths([cp])[0]
    else:
        for cp, w in zip(chunk, ws): results[cp] = w
    done += len(chunk)
    if done % 80000 < B: print(done, '/', len(cps), file=sys.stderr)
    i += B
for cp in sorted(boxrange | {0x0A, 0x0D}):
    results[cp] = 1 if cp in (0x0A,0x0D) else batch_widths([cp])[0]
json.dump({str(k): v for k, v in results.items()}, open('/tmp/widths.json','w'))
print('done', len(results), file=sys.stderr)
